    capacity = _get(instance, "capacity", "vehicle_capacity", "cap", default=None)

    coords = _get(instance, "coords", "coordinates", "locations", "points", default=None)
    demands = _get(instance, "demands", "demand", default=None)

    customers_obj = None
    if type(instance) is dict and "customers" in instance:
        customers_obj = instance["customers"]

    customer_ids = []
    if type(demands) is dict:
        for k in demands:
            if k != depot_id:
                customer_ids.append(k)
    elif type(coords) is dict:
        for k in coords:
            if k != depot_id:
                customer_ids.append(k)
    elif type(customers_obj) is list:
        for c in customers_obj:
            if type(c) is dict and "id" in c:
                cid = c["id"]
                if cid != depot_id:
                    customer_ids.append(cid)
    elif type(instance) is dict:
        for k in instance:
            if _is_num(k) and k != depot_id:
                customer_ids.append(k)

    seen = {}
    uniq = []
    for cid in customer_ids:
        if cid not in seen:
            seen[cid] = 1
            uniq.append(cid)
    customer_ids = uniq

    def demand_of(cid):
        if type(demands) is dict:
            v = demands.get(cid, 0)
            return v if _is_num(v) and v > 0 else 0
        if type(customers_obj) is list:
            for c in customers_obj:
                if type(c) is dict and c.get("id") == cid:
                    v = c.get("demand", 0)
                    return v if _is_num(v) and v > 0 else 0
        return 0

    def coord_of(cid):
        if type(coords) is dict:
            return coords.get(cid, None)
        if type(customers_obj) is list:
            for c in customers_obj:
                if type(c) is dict and c.get("id") == cid:
                    v = c.get("coord", c.get("coords", c.get("location", None)))
                    return v
        return None

    depot_coord = coord_of(depot_id)
    has_coords = depot_coord is not None
    if has_coords:
        for cid in customer_ids:
            if coord_of(cid) is None:
                has_coords = False
                break

    def dist(a, b):
        if not has_coords:
            return 0
        pa = coord_of(a)
        pb = coord_of(b)
        dx = pa[0] - pb[0]
        dy = pa[1] - pb[1]
        return (dx * dx + dy * dy) ** 0.5

    total_demand = 0
    max_d = 0
    for cid in customer_ids:
        d = demand_of(cid)
        total_demand += d
        if d > max_d:
            max_d = d
    if capacity is None:
        capacity = total_demand if total_demand > 0 else max_d
    if capacity is None or capacity <= 0:
        capacity = max_d if max_d > 0 else 1

    oversized = []
    normal = []
    for cid in customer_ids:
        if demand_of(cid) > capacity:
            oversized.append(cid)
        else:
            normal.append(cid)

    def route_load(route):
        s = 0
        for cid in route:
            s += demand_of(cid)
        return s

    def route_cost(route):
        if not has_coords or not route:
            return 0
        c = dist(depot_id, route[0]) + dist(route[-1], depot_id)
        i = 0
        while i + 1 < len(route):
            c += dist(route[i], route[i + 1])
            i += 1
        return c

    def insertion_cost(route, pos, cid):
        if not has_coords:
            return 0
        before = depot_id if pos == 0 else route[pos - 1]
        after = depot_id if pos == len(route) else route[pos]
        return dist(before, cid) + dist(cid, after) - dist(before, after)

    if has_coords:
        dx0, dy0 = depot_coord
        ordered = []
        for cid in normal:
            x, y = coord_of(cid)
            vx = x - dx0
            vy = y - dy0
            if vx >= 0 and vy >= 0:
                q = 0
                key = vy / (vx + 1e-12)
            elif vx < 0 and vy >= 0:
                q = 1
                key = -vx / (vy + 1e-12)
            elif vx < 0 and vy < 0:
                q = 2
                key = vy / (vx - 1e-12)
            else:
                q = 3
                key = -vx / (abs(vy) + 1e-12)
            ordered.append((q * 10**9 + key, dist(depot_id, cid), cid))
        ordered.sort(key=lambda t: (t[0], t[1], t[2]))
        ordered = [t[2] for t in ordered]
    else:
        ordered = sorted(normal, key=lambda c: (-demand_of(c), c))

    routes = []
    cur = []
    load = 0
    for cid in ordered:
        d = demand_of(cid)
        if cur and load + d > capacity:
            routes.append(cur)
            cur = [cid]
            load = d
        else:
            cur.append(cid)
            load += d
    if cur:
        routes.append(cur)

    for cid in oversized:
        routes.append([cid])

    # Repair missing / duplicated customers if any
    present = {}
    repaired = []
    for r in routes:
        nr = []
        for cid in r:
            if cid not in present:
                present[cid] = 1
                nr.append(cid)
        if nr:
            repaired.append(nr)
    routes = repaired
    missing = []
    for cid in customer_ids:
        if cid not in present:
            missing.append(cid)
    for cid in missing:
        d = demand_of(cid)
        best_r = -1
        best_p = 0
        best_delta = None
        for ri in range(len(routes)):
            if route_load(routes[ri]) + d > capacity:
                continue
            route = routes[ri]
            for p in range(len(route) + 1):
                delta = insertion_cost(route, p, cid)
                if best_delta is None or delta < best_delta or (delta == best_delta and (ri < best_r or (ri == best_r and p < best_p))):
                    best_delta = delta
                    best_r = ri
                    best_p = p
        if best_r >= 0:
            routes[best_r].insert(best_p, cid)
        else:
            routes.append([cid])

    # Simple local improvement: relocate customers if it reduces total cost and remains feasible
    if has_coords and len(routes) > 1:
        improved = True
        guard = 0
        while improved and guard < 3:
            guard += 1
            improved = False
            i = 0
            while i < len(routes):
                r1 = routes[i]
                j = 0
                while j < len(r1):
                    cid = r1[j]
                    d = demand_of(cid)
                    best_move = None
                    base_cost = route_cost(r1)
                    k = 0
                    while k < len(routes):
                        if k != i and route_load(routes[k]) + d <= capacity:
                            r2 = routes[k]
                            p = 0
                            while p <= len(r2):
                                new_r1 = r1[:j] + r1[j + 1:]
                                new_r2 = r2[:p] + [cid] + r2[p:]
                                old = base_cost + route_cost(r2)
                                new = route_cost(new_r1) + route_cost(new_r2)
                                if new + 1e-12 < old:
                                    best_move = (k, p, new_r1, new_r2)
                                    break
                                p += 1
                            if best_move is not None:
                                break
                        k += 1
                    if best_move is not None:
                        k, p, new_r1, new_r2 = best_move
                        routes[i] = new_r1
                        routes[k] = new_r2
                        improved = True
                        if len(routes[i]) == 0:
                            routes.pop(i)
                            i -= 1
                            break
                    j += 1
                i += 1

    # Final cleanup: remove empties, ensure deterministic order
    final_routes = []
    for r in routes:
        if r:
            final_routes.append(r)

    return final_routes
